# Generated by scripts/build-deploy.sh — do not edit directly.
# setup-modal.ps1 -- Installs/updates Modal CLI on Windows
# Safe to re-run -- detects existing install and upgrades as needed.
#
# Windows: Uses uv tool (preferred) or pip --user (fallback). Requires Python 3.10+.
#
# Authentication (modal setup) is interactive and must be run separately
# after install -- not automated by this script.
#
# See reference/tool-registry.md for install source details.

# --- Shared library ---
# aitools-lib.ps1 -- shared helpers for all aitools PowerShell scripts
# Dot-sourced, not executed directly.
#
# Provides: ReadConfigKey, Initialize-Logging, Log/LogOk/LogError/LogWarn,
# Write-Summary, Show-Summary.
#
# Usage:
#   . (Join-Path (Split-Path -Parent $MyInvocation.MyCommand.Path) "aitools-lib.ps1")
#   Initialize-Logging "script-name"
#
# Entry points (aitools.ps1, aitools-install.ps1) override log functions after
# sourcing for specialized logging (file-only, JSONL, etc.).
#
# Platform detection uses PS 7+ built-in $IsMacOS/$IsWindows -- no custom variables.

# ---------------------------------------------------------------------------
# Config reader (PS 5.1 compatible)
# ---------------------------------------------------------------------------
function ReadConfigKey {
    param([string]$File, [string]$Key)
    if (-not (Test-Path $File)) { return $null }
    try {
        $json = Get-Content $File -Raw -ErrorAction Stop | ConvertFrom-Json
        $val = $json.$Key
        if ($val) { return $val }
    } catch {
        # File exists but is invalid JSON -- warn so callers know the null
        # return means "corrupt", not "missing key"
        Write-Host "      WARN: could not parse $File" -ForegroundColor Yellow
    }
    return $null
}

# ---------------------------------------------------------------------------
# Logging init
# ---------------------------------------------------------------------------
# Sets $script:scriptName, $script:logDir, $script:logFile; resets
# $script:errors, $script:warnings. Creates log directory.
# Usage: Initialize-Logging "setup-foo"
function Initialize-Logging {
    param([Parameter(Mandatory)][string]$Name)
    $script:scriptName = $Name
    if ($IsWindows -or (-not (Test-Path variable:IsMacOS))) {
        # Windows (PS 7+) or PS 5.1 (always Windows)
        $script:logDir = Join-Path $env:LOCALAPPDATA "aitools"
    } else {
        # macOS/Linux
        $script:logDir = Join-Path $HOME "Library/Logs/aitools"
    }
    $script:logFile = Join-Path $script:logDir "deploy.log"
    if (-not (Test-Path $script:logDir)) {
        New-Item -ItemType Directory -Path $script:logDir -Force | Out-Null
    }
    $script:errors = 0
    $script:warnings = 0
}

# ---------------------------------------------------------------------------
# Standard logging (console + log file, with [level] tag)
# ---------------------------------------------------------------------------
function Log($msg, $level = "info") {
    $ts = (Get-Date).ToUniversalTime().ToString("yyyy-MM-ddTHH:mm:ssZ")
    $line = "[$ts] [$scriptName] [$level] $msg"
    Add-Content -Path $logFile -Value $line
    switch ($level) {
        "error" { Write-Host $line -ForegroundColor Red }
        "warn"  { Write-Host $line -ForegroundColor Yellow }
        default { Write-Host $line }
    }
}
function LogOk($msg)    { Log $msg "ok" }
function LogError($msg) { Log $msg "error"; $script:errors++ }
function LogWarn($msg)  { Log $msg "warn"; $script:warnings++ }

# ---------------------------------------------------------------------------
# Summary writer (3-arg: category, tool, detail)
# ---------------------------------------------------------------------------
function Write-Summary($cat, $tool, $detail) {
    if ($env:AITOOLS_SUMMARY_FILE) {
        Add-Content -Path $env:AITOOLS_SUMMARY_FILE -Value "${cat}|${tool}|${detail}"
    }
}

# ---------------------------------------------------------------------------
# Summary panel renderer
# ---------------------------------------------------------------------------
# Reads AITOOLS_SUMMARY_FILE, displays colored panel, cleans up.
# Silent no-op if file unset, missing, or empty.
function Show-Summary {
    $sfile = $env:AITOOLS_SUMMARY_FILE
    if (-not $sfile -or -not (Test-Path $sfile)) { return }
    $lines = Get-Content $sfile -ErrorAction SilentlyContinue
    if (-not $lines) { Remove-Item $sfile -ErrorAction SilentlyContinue; return }

    # Dedup by tool name: highest severity wins (ERROR > WARN > OK).
    # ACTIONs (empty tool name) are never deduped.
    $rank = @{ 'OK' = 1; 'WARN' = 2; 'ERROR' = 3 }
    $order = [System.Collections.Generic.List[string]]::new()
    $best = @{}
    $bestDetail = @{}
    $actions = [System.Collections.Generic.List[string]]::new()

    foreach ($line in $lines) {
        $parts = $line -split '\|', 3
        $cat = $parts[0]
        $tool = $parts[1]
        $det = $parts[2]
        if ($cat -eq 'ACTION' -or $tool -eq '') {
            $actions.Add($line)
            continue
        }
        $r = if ($rank.ContainsKey($cat)) { $rank[$cat] } else { 0 }
        if (-not $best.ContainsKey($tool)) {
            $order.Add($tool)
            $best[$tool] = $cat
            $bestDetail[$tool] = $det
        } elseif ($r -gt $rank[$best[$tool]]) {
            $best[$tool] = $cat
            $bestDetail[$tool] = $det
        }
    }

    # Build deduped lines
    $deduped = [System.Collections.Generic.List[string]]::new()
    foreach ($t in $order) {
        $deduped.Add("$($best[$t])|$t|$($bestDetail[$t])")
    }
    foreach ($a in $actions) {
        $deduped.Add($a)
    }

    Write-Host ""
    Write-Host "------------------------------------------------------------"
    foreach ($line in $deduped) {
        $parts = $line -split '\|', 3
        if ($parts[0] -eq 'OK') { Write-Host ("  [ok]  {0,-16} {1}" -f $parts[1], $parts[2]) -ForegroundColor Green }
    }
    foreach ($line in $deduped) {
        $parts = $line -split '\|', 3
        if ($parts[0] -eq 'WARN') { Write-Host ("  [!]   {0,-16} {1}" -f $parts[1], $parts[2]) -ForegroundColor Yellow }
    }
    foreach ($line in $deduped) {
        $parts = $line -split '\|', 3
        if ($parts[0] -eq 'ERROR') { Write-Host ("  [ERR] {0,-16} {1}" -f $parts[1], $parts[2]) -ForegroundColor Red }
    }
    $firstAction = $true
    foreach ($line in $deduped) {
        $parts = $line -split '\|', 3
        if ($parts[0] -eq 'ACTION') {
            if ($firstAction) {
                Write-Host ""
                Write-Host "  ACTION REQUIRED -- run before tools are ready:" -ForegroundColor Magenta
                $firstAction = $false
            }
            Write-Host "  >>  $($parts[2])" -ForegroundColor Magenta
        }
    }
    Write-Host "------------------------------------------------------------"
    Remove-Item $sfile -ErrorAction SilentlyContinue
}
Initialize-Logging "setup-modal"

# --- OS guard ---
if ($PSVersionTable.PSVersion.Major -ge 6 -and -not $IsWindows) {
    LogError "This script is for Windows. On macOS/Linux, use the .sh version."
    exit 1
}

# Helper: refresh PATH from registry (picks up pip installs in same session)
function Refresh-Path {
    $machinePath = [Environment]::GetEnvironmentVariable("Path", "Machine")
    $userPath = [Environment]::GetEnvironmentVariable("Path", "User")
    $env:Path = "$machinePath;$userPath"
}

# Helper: find Python user scripts directory and add to PATH if needed
function Ensure-PythonUserScriptsOnPath {
    if (-not $pythonCmd) { return }
    # nt_user scheme gives the user-install scripts directory on Windows
    $scriptsDir = & $pythonCmd -c "import sysconfig; print(sysconfig.get_path('scripts', 'nt_user'))" 2>$null
    if (-not $scriptsDir -or -not (Test-Path $scriptsDir)) { return }
    $userPath = [Environment]::GetEnvironmentVariable("Path", "User")
    if ($userPath -notlike "*$scriptsDir*") {
        [Environment]::SetEnvironmentVariable("Path", "$userPath;$scriptsDir", "User")
        Log "Added Python user Scripts to persistent PATH: $scriptsDir"
    }
    if ($env:Path -notlike "*$scriptsDir*") {
        $env:Path = "$scriptsDir;$env:Path"
    }
}

# Refresh PATH to pick up tools installed by prior steps (e.g., setup-python, setup-uv)
Refresh-Path

# Verify Python 3.10+
$pythonCmd = $null
if (Get-Command python -ErrorAction SilentlyContinue) {
    $pythonCmd = "python"
} elseif (Get-Command python3 -ErrorAction SilentlyContinue) {
    $pythonCmd = "python3"
}

if ($pythonCmd) {
    $pyVersionStr = & $pythonCmd -c "import sys; print(str(sys.version_info.major) + '.' + str(sys.version_info.minor))" 2>$null
    if ($pyVersionStr -match '^(\d+)\.(\d+)') {
        $pyMajor = [int]$Matches[1]
        $pyMinor = [int]$Matches[2]
        if ($pyMajor -lt 3 -or ($pyMajor -eq 3 -and $pyMinor -lt 10)) {
            LogError "Python 3.10+ required. Found Python $pyVersionStr"
            Write-Summary "ERROR" "modal cli" "Python 3.10+ required (found $pyVersionStr)"
            exit 1
        }
        Log "Python $pyVersionStr found ($pythonCmd)"
    }
}

# --- Install/update ---
# Get-Command exempt: command-existence check with if/else fallback
if (Get-Command uv -ErrorAction SilentlyContinue) {
    # Get-Command exempt: command-existence check with if/else fallback
    if (Get-Command modal -ErrorAction SilentlyContinue) {
        $modalVersion = & modal --version 2>$null
        if (-not $modalVersion) { $modalVersion = "version unknown" }
        LogOk "Modal CLI already installed ($modalVersion)"
        Log "Upgrading via uv tool..."
        $toolOutput = & uv tool upgrade modal 2>&1 | Out-String
        $toolOutput.Trim().Split("`n") | ForEach-Object { Log $_.TrimEnd() }
        if ($LASTEXITCODE -ne 0) {
            LogError "uv tool upgrade modal failed (exit code $LASTEXITCODE)"
            Write-Summary "ERROR" "modal cli" "uv tool upgrade failed"
        } elseif (Get-Command modal -ErrorAction SilentlyContinue) {
            $modalVersion = & modal --version 2>$null
            if (-not $modalVersion) { $modalVersion = "version unknown" }
            LogOk "Modal CLI upgraded ($modalVersion)"
            Write-Summary "OK" "modal cli" "$modalVersion"
        }
    } else {
        Log "Installing Modal CLI via uv tool..."
        $toolOutput = & uv tool install modal 2>&1 | Out-String
        $toolOutput.Trim().Split("`n") | ForEach-Object { Log $_.TrimEnd() }
        if ($LASTEXITCODE -ne 0) {
            LogError "uv tool install modal failed (exit code $LASTEXITCODE)"
            Write-Summary "ERROR" "modal cli" "uv tool install failed"
        }
        Refresh-Path
        # Get-Command exempt: command-existence check with if/else fallback
        if (Get-Command modal -ErrorAction SilentlyContinue) {
            $modalVersion = & modal --version 2>$null
            if (-not $modalVersion) { $modalVersion = "version unknown" }
            $modalPath = (Get-Command modal).Source
            LogOk "Modal CLI installed ($modalVersion)"
            Log "Install path: $modalPath"
            Write-Summary "OK" "modal cli" "$modalVersion"
        } else {
            LogError "uv tool install completed but 'modal' not found in PATH"
            LogWarn "Ensure ~/.local/bin is in PATH"
            Write-Summary "ERROR" "modal cli" "installed but not on PATH"
        }
    }
} elseif (Get-Command pip -ErrorAction SilentlyContinue) {
    $pipCmd = "pip"
    Log "uv not found -- installing Modal CLI via pip (--user)..."
    $pipOutput = & $pipCmd install --user modal 2>&1 | Out-String
    $pipOutput.Trim().Split("`n") | ForEach-Object { Log $_.TrimEnd() }
    if ($LASTEXITCODE -ne 0 -or $pipOutput -match '(?m)^ERROR:') {
        LogError "pip install --user modal failed (see log above)"
        Write-Summary "ERROR" "modal cli" "pip install failed"
    }
    Refresh-Path
    Ensure-PythonUserScriptsOnPath
    # Get-Command exempt: command-existence check with if/else fallback
    if (Get-Command modal -ErrorAction SilentlyContinue) {
        $modalVersion = & modal --version 2>$null
        if (-not $modalVersion) { $modalVersion = "version unknown" }
        LogOk "Modal CLI installed ($modalVersion)"
        Write-Summary "OK" "modal cli" "$modalVersion"
    } else {
        LogError "pip install completed but 'modal' not found in PATH"
        Write-Summary "ERROR" "modal cli" "installed but not on PATH"
    }
} else {
    LogError "No package installer found. Install uv or pip first."
    Write-Summary "ERROR" "modal cli" "no package installer (uv/pip) found"
}

# Only suggest auth if modal is installed but not yet authenticated
# Get-Command exempt: command-existence check with if/else fallback
if (Get-Command modal -ErrorAction SilentlyContinue) {
    $modalToml = Join-Path $HOME ".modal.toml"
    if (-not (Test-Path $modalToml)) {
        LogWarn "Authentication required: run 'modal setup' to authenticate (browser flow)"
        Write-Summary "ACTION" "" "modal setup -- authenticate modal (browser flow)"
    }
}

# --- Exit ---
if ($errors -gt 0) {
    Log "FAILED with $errors error(s). See log: $logFile" "error"
    exit 1
} elseif ($warnings -gt 0) {
    Log "COMPLETED with $warnings warning(s)" "warn"
    exit 0
} else {
    Log "COMPLETED successfully" "ok"
    exit 0
}
